/**
 * shared/i18n-en.js — the bulk of the VI → EN dictionary for shared/i18n.js.
 *
 * Kept out of i18n.js so Vietnamese-mode visitors (most of them) never
 * download it: i18n.js injects this file only once English is switched on,
 * merges it with EWSI18n.extend() and re-applies the page.
 *
 * Keys are the visible Vietnamese text of one text node or attribute, with
 * whitespace collapsed and any leading emoji / arrows / bullets and trailing
 * ":" "*" "…" left off — i18n.js strips those before looking up and puts
 * them back afterwards, so "📚 Từ vựng" and "Từ vựng:" both hit "Từ vựng".
 * A sentence split by <b>/<a> tags reaches the page as separate text nodes,
 * so it is listed here fragment by fragment.
 *
 * Add new UI strings here. Lesson content stays Vietnamese on purpose.
 */
