    'Đây là danh sách đề Full test — mỗi đề có 3 passages và 40 câu hỏi. Gõ tên đề vào ô tìm kiếm ở trên để tìm nhanh, hoặc bấm vào một đề để bắt đầu làm bài có tính giờ.': 'This is the Full test list — each test has 3 passages and 40 questions. Type a test name in the search box above to find it quickly, or click a test to start a timed attempt.',
    'Đây là danh sách đề Full test Listening. Gõ tên đề vào ô tìm kiếm ở trên để tìm nhanh, hoặc bấm vào một đề để bắt đầu làm bài có tính giờ và phát audio.': 'This is the Full Listening test list. Type a test name in the search box above to find it quickly, or click a test to start a timed attempt with audio.',
    'Đây là nơi bạn vào từng kỹ năng: Reading, Listening, Writing, Speaking, Luyện viết — mỗi mục đều có bài luyện lẻ và full đề thi thử. Trên điện thoại, bấm biểu tượng ☰ để mở menu.': 'This is where you get to each skill: Reading, Listening, Writing, Speaking, Writing drills — each has single practice and full mock tests. On a phone, tap ☰ to open the menu.',
    'Đây là sổ từ vựng cá nhân của bạn. Khi luyện tập ở bất kỳ trang nào, lưu từ mới vào đây rồi quay lại ôn tập bất cứ lúc nào.': 'This is your personal vocabulary notebook. Whenever you practise on any page, save new words here and come back to review them any time.',
    'Đeo tai nghe vô nè, Lumi nghe cùng cậu': 'Put your headphones on, Lumi will listen with you',
