    'để "mở khoá Premium" hay "hack điểm", đó là lừa đảo — họ sẽ chiếm tài khoản của bạn.': 'to "unlock Premium" or "hack scores", it\'s a scam — they\'ll take over your account.',
    'Đề bài': 'Prompt',
    'Đề Cambridge giao diện như thi máy thật, audio phát 1 lần.': 'Cambridge tests in a real computer-exam interface, audio plays once.',
