    'để chấm. (Bạn cũng có thể tự gõ vào ô bên dưới nếu muốn.)': 'to be marked. (You can also type in the box below if you like.)',
    'để chèn vào bài.': 'to insert it into your essay.',
    'để chèn vào ô đang viết (chỗ con trỏ), rồi chỉnh lại cho hợp đoạn văn.': 'to insert it into the box you\'re writing in (at the cursor), then adjust it to fit the paragraph.',
