    'để đưa các từ vào sổ từ vựng. Hệ thống sẽ nhắc bạn ôn từng từ đúng lúc.': 'to put the words into a vocabulary notebook. The system will remind you to review each word at the right time.',
    'để được chấm điểm.': 'to be marked.',
    'để ghi âm, hệ thống so từng từ với câu gốc. Bấm': 'to record; the system compares each word with the original sentence. Click',
    'để hiểu nghĩa một cụm tiếng Anh. Mỗi kết quả có cụm tương đương và câu gợi ý kiểu IELTS.': 'to understand an English phrase. Each result has equivalent phrases and IELTS-style example sentences.',
    'để hiểu vì sao sai.': 'to understand why it was wrong.',
    'Đề IELTS hơi khó bạn nhỉ, mình cố tiếp cùng nhau nha, từ từ sẽ giỏi thôi!': 'IELTS tests are a bit tough, right? Let\'s keep going together — you\'ll get better step by step!',
    'để khôi phục lại đúng số ngày đã mất!': 'to restore exactly the days you lost!',
