    'Điểm mạnh': 'Strengths',
    'Điểm này thấp hơn cả nhiệt độ điều hòa 🥶 Nhưng ai cũng phải bắt đầu từ đâu đó — cứ cày là lên!': 'This score is lower than the air-con temperature 🥶 But everyone starts somewhere — keep grinding and it\'ll go up!',
    'Điểm Pronunciation được AI ước tính dựa trên văn bản chuyển giọng nói (từ nối, ngập ngừng, lựa chọn từ), không phân tích trực tiếp âm thanh phát âm của bạn. Coi đây là tham khảo, không thay thế đánh giá phát âm từ giáo viên.': 'The Pronunciation score is estimated by AI from the speech-to-text transcript (linking words, hesitation, word choice); it doesn\'t analyse the sound of your pronunciation directly. Treat it as a guide, not a replacement for your teacher\'s pronunciation assessment.',
    'Điểm Pronunciation được chấm trực tiếp từ bản ghi âm của bạn — âm tiết, trọng âm từ/câu, ngữ điệu, nhịp điệu và nối âm. Vẫn nên kết hợp nhận xét phát âm từ giáo viên.': 'The Pronunciation score is marked directly from your recording — syllables, word/sentence stress, intonation, rhythm and linking. It\'s still worth combining with your teacher\'s pronunciation feedback.',
    'Điểm TB Quiz từ vựng (từ 5 câu) — bằng điểm thì ai nhanh hơn xếp trên.': 'Average vocabulary quiz score (from 5 questions) — on a tie, the faster student ranks higher.',
