    'đúng': 'correct',
    'Đúng là': 'It\'s',
    'Đúng liên tiếp 3–10 câu sẽ kích hoạt combo thưởng. Duy trì thói quen học mỗi ngày để tăng streak.': 'Getting 3–10 in a row triggers a bonus combo. Keep a daily study habit to grow your streak.',
    'đúng với mức nhớ thật. Hệ thống dựa vào đó để hẹn ngày ôn từng cụm (lặp lại ngắt quãng), nên chấm "Đã thuộc" quá sớm là tự làm mình quên.': 'honestly. The system uses it to schedule each phrase\'s review (spaced repetition), so marking "Learned" too early just makes you forget.',
