    'Đừng buồn nha, Lulu ôm một cái 🤗 Mình làm lại từ từ thôi!': 'Don\'t be sad, Lulu gives you a hug 🤗 Let\'s take it slowly again!',
    'Đừng đọc từng chữ. Lướt câu chủ đề để nắm “bản đồ” của bài: đoạn nào nói về gì.': 'Don\'t read word by word. Skim the topic sentences to get a "map" of the passage: which paragraph is about what.',
