    'được tra từ, dịch, không giám sát — để học và ôn.': 'dictionary and translation allowed, no proctoring — for learning and review.',
    'Đường dẫn bạn vừa mở không tồn tại hoặc đã được thay đổi — có thể bài học/đề thi này đã bị xoá, hoặc liên kết đã hết hạn. Kiểm tra lại đường dẫn, hoặc quay về trang chủ để tiếp tục.': 'The link you opened doesn\'t exist or has changed — the lesson/test may have been deleted, or the link has expired. Check the link, or go back to the home page to continue.',
    'Email chuyên nghiệp, meeting, thuyết trình, đàm phán bằng tiếng Anh. Từ vựng Business English thực chiến.': 'Professional emails, meetings, presentations and negotiation in English. Practical Business English vocabulary.',
