    'Full đề: làm bài đầy đủ 3 passages trong 60 phút, tính band điểm như thi thật. Bài lẻ: luyện từng passage riêng theo chủ đề. Reading Tips: chiến lược làm từng dạng câu hỏi.': 'Full test: a complete 3-passage test in 60 minutes, scored like the real exam. Single items: practise one passage at a time by topic. Reading Tips: strategies for each question type.',
    'Full đề: làm bài đầy đủ 4 sections trong 30 phút, tính band điểm như thi thật. Bài lẻ: luyện từng section riêng. Listening Tips: chiến lược nghe theo từng dạng câu hỏi.': 'Full test: a complete 4-section test in 30 minutes, scored like the real exam. Single items: practise one section at a time. Listening Tips: listening strategies for each question type.',
