    'Luyện tập: chọn đề Part 1, 2, 3 và ghi âm để nhận AI feedback ngay. Thi thử đầy đủ: mô phỏng bài thi hoàn chỉnh. Lịch sử, Tài liệu và Speaking Tips cũng nằm ở đây.': 'Practice: pick a Part 1, 2 or 3 question and record to get AI feedback right away. Full mock test: a complete simulated exam. History, Materials and Speaking Tips are here too.',
    'Luyện tập: làm từng câu về ngữ pháp Task 1 (Noun Phrase, mô tả dữ liệu, so sánh, xu hướng...), có gợi ý và phản hồi ngay. Thi thử: làm một bộ đề ngẫu nhiên không gợi ý, giống thi thật.': 'Practice: one question at a time on Task 1 grammar (Noun Phrase, describing data, comparisons, trends...), with hints and instant feedback. Mock test: a random set with no hints, like the real exam.',
    'Luyện tập: làm từng câu, có gợi ý và nhận phản hồi ngay sau mỗi câu — tích lũy XP và combo. Thi thử: làm một bộ đề ngẫu nhiên không có gợi ý, giống thi thật, xem đáp án sau khi nộp.': 'Practice: one question at a time with hints and instant feedback after each — earn XP and combos. Mock test: a random set with no hints, like the real exam; see the answers after you submit.',
    'Luyện tập: Quy trình hoàn chỉnh': 'Practice: the complete process',
    'Luyện tất cả N từ': 'Practise all N words',
    'Luyện tất cả từ?': 'Practise all words?',
