    'Luyện topic này': 'Practise this topic',
    'Luyện từ vựng yếu': 'Practise weak words',
    'Luyện từ vựng, làm đề Reading hoặc Listening đúng': 'Practise vocabulary, or do Reading or Listening tests with',
    'Mỗi phiên luyện tập: Từ vựng đúng ≥ 70% / 80% / 90% được +1 / +2 / +3 🔥; Reading, Listening đúng ≥ 50% / 70% / 90% được +1 / +2 / +3 🔥; các bài khác (Gap-fill, Dictation, Shadowing, Grammar, Writing, Speaking…) +1–2 🔥. Tối đa 10 🔥/ngày. Bỏ học trọn 1 ngày sẽ mất streak.': 'Each practice session: Vocabulary ≥ 70% / 80% / 90% correct earns +1 / +2 / +3 🔥; Reading or Listening ≥ 50% / 70% / 90% earns +1 / +2 / +3 🔥; other practice (Gap-fill, Dictation, Shadowing, Grammar, Writing, Speaking…) earns +1–2 🔥. Up to 10 🔥 a day. Missing a whole day loses your streak.',
    'Luyện từng kỹ năng riêng biệt để viết Task 1 đạt điểm cao. Chọn cấp độ và kỹ năng, rồi bắt đầu!': 'Practise each skill separately to score high in Task 1. Pick a level and a skill, then get started!',
