    'Mỗi đề là một buổi học trọn vẹn: chuẩn bị từ vựng & ý tưởng → viết nửa bài trên lớp → hoàn thành ở nhà.': 'Each prompt is a complete lesson: prepare vocabulary & ideas → write half the essay in class → finish it at home.',
