    'Trình duyệt đang chặn micro. Bấm biểu tượng khoá 🔒 trên thanh địa chỉ → cho phép Micro → tải lại trang.': 'The browser is blocking the microphone. Click the lock 🔒 in the address bar → allow Microphone → reload the page.',
    'Trình duyệt không hỗ trợ ghi âm cho phần luyện nói này. Vui lòng dùng Google Chrome.': 'This browser doesn\'t support recording for this speaking practice. Please use Google Chrome.',
    'Trình duyệt không hỗ trợ ghi âm. Bạn có thể gõ câu trả lời vào ô bên dưới.': 'This browser doesn\'t support recording. You can type your answer in the box below.',
    'Trình duyệt không kết nối được dịch vụ nhận dạng giọng nói (hay gặp trên Brave/Firefox). Bản ghi âm vẫn tiếp tục — cứ nói bình thường, bấm "Dừng" khi xong rồi gõ lại lời thoại vào ô Transcript.': 'The browser can\'t connect to speech recognition (common on Brave/Firefox). Recording continues — just speak normally, click "Stop" when you\'re done, then type what you said into the Transcript box.',
    'Trình duyệt không kết nối được dịch vụ nhận dạng giọng nói (hay gặp trên Brave/Firefox). Vui lòng dùng Google Chrome, hoặc bấm "Ghi nhận câu trả lời" để bỏ qua câu này.': 'The browser can\'t connect to speech recognition (common on Brave/Firefox). Please use Google Chrome, or click "Save my answer" to skip this question.',
    'Trình duyệt này không hỗ trợ ghi âm.': 'This browser doesn\'t support recording.',
    'Trình duyệt này không hỗ trợ nhận diện giọng nói nên không chấm điểm được — bạn vẫn có thể ghi âm và tự nghe lại để so sánh. Hãy dùng': 'This browser doesn\'t support speech recognition, so it can\'t score you — you can still record and listen back to compare. Please use',
    'Trình duyệt này không tạo phụ đề trực tiếp khi ghi âm. Cứ bấm mic và': 'This browser doesn\'t make live captions while recording. Just tap the mic and',
    'Trình duyệt này không tạo phụ đề tự động — bạn vẫn bấm để ghi âm, giáo viên sẽ chấm từ bản ghi.': 'This browser doesn\'t make captions automatically — you can still click to record, and the teacher will mark from the recording.',
    'Trình duyệt này không tự nhận diện giọng nói (Chrome trên máy tính thường có). Bạn vẫn ghi âm được để nghe lại — hãy mở mục "Bản ghi lời nói" bên dưới và tự gõ nội dung trước khi nộp.': 'This browser doesn\'t recognise speech automatically (Chrome on a computer usually does). You can still record to listen back — open "Speech transcript" below and type it in yourself before submitting.',
