    'Từ giữ nguyên trạng thái ghi nhớ & lịch ôn. Từ đã có sẵn ở sổ đích sẽ không bị nhân đôi. Sổ đích tối đa 500 từ — phần không vừa sẽ ở lại sổ hiện tại.': 'Words keep their memory status & review schedule. Words already in the target notebook won\'t be duplicated. The target notebook holds up to 500 words — anything that doesn\'t fit stays in the current notebook.',
